SourceCode.Declaration:
/// <summary>
/// Dialog contract for the cleanup batch: how many days of log data to keep.
/// Implements SysOperationInitializable so the framework pre-fills the dialog defaults.
/// </summary>
[DataContract]
internal final class CELTCleanupContract extends SysOperationDataContractBase implements SysOperationInitializable
{
    Counter keepDataForDays;
}

Method.Source:
[DataMember, SysOperationLabel(literalStr("@CELTLabels:KeepDataForDays"))]
public Counter parmKeepDataForDays(Counter _keepDataForDays = keepDataForDays)
{
    // A zero/blank value (including a stale saved value) falls back to the configured default,
    // mirroring the original contract's coercion, so the dialog always shows the real window.
    if (_keepDataForDays <= 0)
    {
        keepDataForDays = CELTCleanupContract::defaultDays();
    }
    else
    {
        keepDataForDays = _keepDataForDays;
    }

    return keepDataForDays;
}

/// <summary>
/// Pre-fills the dialog with the configured retention (30 when parameters are unset).
/// </summary>
public void initialize()
{
    keepDataForDays = CELTCleanupContract::defaultDays();
}

/// <summary>
/// The configured retention window: CELTParameters.RetentionDays, or 30 when unset.
/// </summary>
/// <returns>days to keep</returns>
public static Counter defaultDays()
{
    CELTParameters parameter = CELTParameters::find();

    return parameter.RetentionDays > 0 ? parameter.RetentionDays : 30;
}
